//! A small backtracking regular expression engine.
//!
//! Supports the subset of the usual syntax that shows up in file queries:
//! literals, `.`, character classes, anchors, alternation, groups, the
//! `* + ? {n,m}` repetitions (greedy and lazy), inline `(?i)` flags and the
//! common `\d \w \s \b` escapes.

#[derive(Debug, Clone)]
enum Node {
    Empty,
    Char(char),
    AnyChar,
    Class(Class),
    Start,
    End,
    WordBoundary(bool),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat {
        node: Box<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
    Group(Box<Node>),
}

#[derive(Debug, Clone)]
struct Class {
    negated: bool,
    singles: Vec<char>,
    ranges: Vec<(char, char)>,
    classes: Vec<u8>, // 'd', 'D', 'w', 'W', 's', 'S'
}

impl Class {
    fn new() -> Self {
        Class {
            negated: false,
            singles: Vec::new(),
            ranges: Vec::new(),
            classes: Vec::new(),
        }
    }

    fn matches(&self, c: char, ci: bool) -> bool {
        let mut found = self.contains(c);
        if !found && ci {
            for alt in case_variants(c) {
                if self.contains(alt) {
                    found = true;
                    break;
                }
            }
        }
        found != self.negated
    }

    fn contains(&self, c: char) -> bool {
        if self.singles.contains(&c) {
            return true;
        }
        for &(lo, hi) in &self.ranges {
            if c >= lo && c <= hi {
                return true;
            }
        }
        for &k in &self.classes {
            if match_perl_class(k, c) {
                return true;
            }
        }
        false
    }
}

fn case_variants(c: char) -> Vec<char> {
    let mut out = Vec::new();
    for v in c.to_lowercase() {
        if v != c {
            out.push(v);
        }
    }
    for v in c.to_uppercase() {
        if v != c && !out.contains(&v) {
            out.push(v);
        }
    }
    out
}

fn match_perl_class(kind: u8, c: char) -> bool {
    match kind {
        b'd' => c.is_ascii_digit(),
        b'D' => !c.is_ascii_digit(),
        b'w' => c.is_alphanumeric() || c == '_',
        b'W' => !(c.is_alphanumeric() || c == '_'),
        b's' => c.is_whitespace(),
        b'S' => !c.is_whitespace(),
        _ => false,
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

pub struct Regex {
    root: Node,
    case_insensitive: bool,
}

struct Parser<'a> {
    chars: &'a [char],
    pos: usize,
    case_insensitive: bool,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn parse_alt(&mut self) -> Result<Node, String> {
        let mut branches = vec![self.parse_concat()?];
        while self.eat('|') {
            branches.push(self.parse_concat()?);
        }
        if branches.len() == 1 {
            Ok(branches.pop().unwrap())
        } else {
            Ok(Node::Alt(branches))
        }
    }

    fn parse_concat(&mut self) -> Result<Node, String> {
        let mut items: Vec<Node> = Vec::new();
        loop {
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            let atom = self.parse_atom()?;
            let atom = self.parse_quantifier(atom)?;
            items.push(atom);
        }
        match items.len() {
            0 => Ok(Node::Empty),
            1 => Ok(items.pop().unwrap()),
            _ => Ok(Node::Concat(items)),
        }
    }

    fn parse_quantifier(&mut self, atom: Node) -> Result<Node, String> {
        let (min, max) = match self.peek() {
            Some('*') => {
                self.pos += 1;
                (0, None)
            }
            Some('+') => {
                self.pos += 1;
                (1, None)
            }
            Some('?') => {
                self.pos += 1;
                (0, Some(1))
            }
            Some('{') => {
                // Only treat as a repetition when it really looks like one.
                let save = self.pos;
                self.pos += 1;
                let lo = self.parse_number();
                match (lo, self.peek()) {
                    (Some(lo), Some('}')) => {
                        self.pos += 1;
                        (lo, Some(lo))
                    }
                    (Some(lo), Some(',')) => {
                        self.pos += 1;
                        let hi = self.parse_number();
                        if !self.eat('}') {
                            self.pos = save;
                            return Ok(atom);
                        }
                        (lo, hi)
                    }
                    _ => {
                        self.pos = save;
                        return Ok(atom);
                    }
                }
            }
            _ => return Ok(atom),
        };
        let greedy = !self.eat('?');
        if let Some(hi) = max {
            if hi < min {
                return Err("repetition quantifier out of order".to_string());
            }
        }
        Ok(Node::Repeat {
            node: Box::new(atom),
            min,
            max,
            greedy,
        })
    }

    fn parse_number(&mut self) -> Option<u32> {
        let start = self.pos;
        while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
            self.pos += 1;
        }
        if start == self.pos {
            return None;
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        s.parse().ok()
    }

    fn parse_atom(&mut self) -> Result<Node, String> {
        let c = match self.next() {
            Some(c) => c,
            None => return Ok(Node::Empty),
        };
        match c {
            '(' => {
                if self.eat('?') {
                    // (?:...) (?i) (?i:...) (?=...) etc.
                    let mut flags = String::new();
                    while let Some(f) = self.peek() {
                        if f == ':' || f == ')' {
                            break;
                        }
                        flags.push(f);
                        self.pos += 1;
                    }
                    if flags.contains('i') {
                        self.case_insensitive = true;
                    }
                    if self.eat(')') {
                        return Ok(Node::Empty);
                    }
                    if !self.eat(':') {
                        return Err("unsupported group syntax".to_string());
                    }
                    let inner = self.parse_alt()?;
                    if !self.eat(')') {
                        return Err("unclosed group".to_string());
                    }
                    Ok(Node::Group(Box::new(inner)))
                } else {
                    let inner = self.parse_alt()?;
                    if !self.eat(')') {
                        return Err("unclosed group".to_string());
                    }
                    Ok(Node::Group(Box::new(inner)))
                }
            }
            ')' => Err("unmatched closing parenthesis".to_string()),
            '[' => self.parse_class(),
            '.' => Ok(Node::AnyChar),
            '^' => Ok(Node::Start),
            '$' => Ok(Node::End),
            '\\' => self.parse_escape(),
            '*' | '+' | '?' => Err("repetition operator missing expression".to_string()),
            _ => Ok(Node::Char(c)),
        }
    }

    fn parse_escape(&mut self) -> Result<Node, String> {
        let c = match self.next() {
            Some(c) => c,
            None => return Err("trailing backslash".to_string()),
        };
        Ok(match c {
            'd' | 'D' | 'w' | 'W' | 's' | 'S' => {
                let mut cl = Class::new();
                cl.classes.push(c as u8);
                Node::Class(cl)
            }
            'b' => Node::WordBoundary(true),
            'B' => Node::WordBoundary(false),
            'n' => Node::Char('\n'),
            'r' => Node::Char('\r'),
            't' => Node::Char('\t'),
            'f' => Node::Char('\u{c}'),
            'v' => Node::Char('\u{b}'),
            '0' => Node::Char('\0'),
            'A' => Node::Start,
            'z' => Node::End,
            'x' => {
                let mut hex = String::new();
                if self.eat('{') {
                    while let Some(h) = self.peek() {
                        if h == '}' {
                            break;
                        }
                        hex.push(h);
                        self.pos += 1;
                    }
                    self.eat('}');
                } else {
                    for _ in 0..2 {
                        if let Some(h) = self.next() {
                            hex.push(h);
                        }
                    }
                }
                let v = u32::from_str_radix(&hex, 16).map_err(|_| "bad hex escape".to_string())?;
                Node::Char(char::from_u32(v).ok_or_else(|| "bad hex escape".to_string())?)
            }
            other => Node::Char(other),
        })
    }

    fn parse_class(&mut self) -> Result<Node, String> {
        let mut cl = Class::new();
        if self.eat('^') {
            cl.negated = true;
        }
        let mut first = true;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return Err("unclosed character class".to_string()),
            };
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            self.pos += 1;
            let lo = if c == '\\' {
                match self.next() {
                    Some(e) => match e {
                        'd' | 'D' | 'w' | 'W' | 's' | 'S' => {
                            cl.classes.push(e as u8);
                            continue;
                        }
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        other => other,
                    },
                    None => return Err("unclosed character class".to_string()),
                }
            } else if c == '[' && self.peek() == Some(':') {
                // POSIX class such as [:alpha:]
                let save = self.pos;
                self.pos += 1;
                let start = self.pos;
                while matches!(self.peek(), Some(ch) if ch.is_ascii_alphabetic()) {
                    self.pos += 1;
                }
                let name: String = self.chars[start..self.pos].iter().collect();
                if self.eat(':') && self.eat(']') {
                    match name.as_str() {
                        "alpha" => {
                            cl.ranges.push(('a', 'z'));
                            cl.ranges.push(('A', 'Z'));
                        }
                        "digit" => cl.classes.push(b'd'),
                        "alnum" => {
                            cl.ranges.push(('a', 'z'));
                            cl.ranges.push(('A', 'Z'));
                            cl.classes.push(b'd');
                        }
                        "space" => cl.classes.push(b's'),
                        "upper" => cl.ranges.push(('A', 'Z')),
                        "lower" => cl.ranges.push(('a', 'z')),
                        "punct" => {
                            for ch in "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".chars() {
                                cl.singles.push(ch);
                            }
                        }
                        _ => return Err("unsupported posix class".to_string()),
                    }
                    continue;
                }
                self.pos = save;
                '['
            } else {
                c
            };
            if self.peek() == Some('-')
                && self.chars.get(self.pos + 1).copied().unwrap_or(']') != ']'
            {
                self.pos += 1;
                let hi = match self.next() {
                    Some('\\') => match self.next() {
                        Some('n') => '\n',
                        Some('r') => '\r',
                        Some('t') => '\t',
                        Some(other) => other,
                        None => return Err("unclosed character class".to_string()),
                    },
                    Some(other) => other,
                    None => return Err("unclosed character class".to_string()),
                };
                cl.ranges.push((lo, hi));
            } else {
                cl.singles.push(lo);
            }
        }
        Ok(Node::Class(cl))
    }
}

struct Matcher<'a> {
    input: &'a [char],
    ci: bool,
    steps: std::cell::Cell<u64>,
}

impl<'a> Matcher<'a> {
    fn char_eq(&self, a: char, b: char) -> bool {
        if a == b {
            return true;
        }
        if self.ci {
            let mut al = a.to_lowercase();
            let mut bl = b.to_lowercase();
            loop {
                match (al.next(), bl.next()) {
                    (None, None) => return true,
                    (Some(x), Some(y)) if x == y => continue,
                    _ => return false,
                }
            }
        }
        false
    }

    fn is_at_boundary(&self, pos: usize) -> bool {
        let before = if pos == 0 {
            false
        } else {
            is_word_char(self.input[pos - 1])
        };
        let after = if pos >= self.input.len() {
            false
        } else {
            is_word_char(self.input[pos])
        };
        before != after
    }

    fn m(&self, node: &Node, pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
        let steps = self.steps.get();
        if steps > 4_000_000 {
            return false;
        }
        self.steps.set(steps + 1);
        match node {
            Node::Empty => k(pos),
            Node::Char(c) => {
                if pos < self.input.len() && self.char_eq(*c, self.input[pos]) {
                    k(pos + 1)
                } else {
                    false
                }
            }
            Node::AnyChar => {
                if pos < self.input.len() && self.input[pos] != '\n' {
                    k(pos + 1)
                } else {
                    false
                }
            }
            Node::Class(cl) => {
                if pos < self.input.len() && cl.matches(self.input[pos], self.ci) {
                    k(pos + 1)
                } else {
                    false
                }
            }
            Node::Start => {
                if pos == 0 {
                    k(pos)
                } else {
                    false
                }
            }
            Node::End => {
                if pos == self.input.len() {
                    k(pos)
                } else {
                    false
                }
            }
            Node::WordBoundary(want) => {
                if self.is_at_boundary(pos) == *want {
                    k(pos)
                } else {
                    false
                }
            }
            Node::Group(inner) => self.m(inner, pos, k),
            Node::Alt(branches) => {
                for b in branches {
                    if self.m(b, pos, k) {
                        return true;
                    }
                }
                false
            }
            Node::Concat(items) => self.m_seq(items, pos, k),
            Node::Repeat {
                node,
                min,
                max,
                greedy,
            } => self.m_repeat(node, *min, *max, *greedy, pos, 0, k),
        }
    }

    fn m_seq(&self, items: &[Node], pos: usize, k: &mut dyn FnMut(usize) -> bool) -> bool {
        match items.split_first() {
            None => k(pos),
            Some((head, tail)) => {
                self.m(head, pos, &mut |p| self.m_seq(tail, p, k))
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn m_repeat(
        &self,
        node: &Node,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        pos: usize,
        done: u32,
        k: &mut dyn FnMut(usize) -> bool,
    ) -> bool {
        let can_more = match max {
            Some(m) => done < m,
            None => true,
        };
        let try_more = |k: &mut dyn FnMut(usize) -> bool| -> bool {
            if !can_more {
                return false;
            }
            self.m(node, pos, &mut |p| {
                if p == pos && done >= min {
                    // zero-width match: stop to avoid infinite loops
                    return false;
                }
                self.m_repeat(node, min, max, greedy, p, done + 1, k)
            })
        };
        if done < min {
            return try_more(k);
        }
        if greedy {
            if try_more(k) {
                return true;
            }
            k(pos)
        } else {
            if k(pos) {
                return true;
            }
            try_more(k)
        }
    }
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut p = Parser {
            chars: &chars,
            pos: 0,
            case_insensitive: false,
        };
        let root = p.parse_alt()?;
        if p.pos != chars.len() {
            return Err("unexpected trailing characters".to_string());
        }
        Ok(Regex {
            root,
            case_insensitive: p.case_insensitive,
        })
    }

    /// Case-insensitive variant used for glob and LIKE patterns.
    pub fn new_ci(pattern: &str) -> Result<Regex, String> {
        let mut re = Regex::new(pattern)?;
        re.case_insensitive = true;
        Ok(re)
    }

    pub fn is_match(&self, text: &str) -> bool {
        let input: Vec<char> = text.chars().collect();
        let m = Matcher {
            input: &input,
            ci: self.case_insensitive,
            steps: std::cell::Cell::new(0),
        };
        for start in 0..=input.len() {
            if m.m(&self.root, start, &mut |_| true) {
                return true;
            }
        }
        false
    }
}

