#[derive(Debug, Clone)]
enum Node {
    Empty,
    Char(char),
    AnyChar,
    Class(Class),
    Start,
    End,
    WordBoundary(bool),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat {
        node: Box<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
    Group(Box<Node>),
