//! Message digests used by the `sha1`, `sha256`, `sha512` and `sha3` columns.

use std::fs::File;
use std::io::{BufReader, Read};

pub enum HashKind {
    Sha1,
    Sha256,
    Sha512,
    Sha3_512,
}

pub fn hash_file(path: &std::path::Path, kind: HashKind) -> Option<String> {
    let file = File::open(path).ok()?;
    let mut reader = BufReader::new(file);
    let mut buf = [0u8; 65536];
    match kind {
        HashKind::Sha1 => {
            let mut h = Sha1::new();
            loop {
                let n = reader.read(&mut buf).ok()?;
                if n == 0 {
                    break;
                }
                h.update(&buf[..n]);
            }
            Some(to_hex(&h.finish()))
        }
        HashKind::Sha256 => {
            let mut h = Sha256::new();
            loop {
                let n = reader.read(&mut buf).ok()?;
                if n == 0 {
                    break;
                }
                h.update(&buf[..n]);
            }
            Some(to_hex(&h.finish()))
        }
        HashKind::Sha512 => {
            let mut h = Sha512::new();
            loop {
                let n = reader.read(&mut buf).ok()?;
                if n == 0 {
                    break;
                }
                h.update(&buf[..n]);
            }
            Some(to_hex(&h.finish()))
        }
        HashKind::Sha3_512 => {
            let mut h = Sha3_512::new();
            loop {
                let n = reader.read(&mut buf).ok()?;
                if n == 0 {
                    break;
                }
                h.update(&buf[..n]);
            }
            Some(to_hex(&h.finish()))
        }
    }
}

pub fn to_hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
    }
    s
}

